```js
const foldPlain = (v) => String(v ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/ß/g,'ss');
const foldGerman = (v) => String(v ?? '').toLowerCase().replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss').normalize('NFD').replace(/[\u0300-\u036f]/g,'');

export function foldText(value) {
  const plain = foldPlain(value);
  const german = foldGerman(value);
  return plain === german ? plain : `${plain} ${german}`;
}

export function matchesQuery(record, query) {
  const needle = String(query ?? '').trim().toLowerCase();
  if (!needle) return true;
  const haystack = foldText(titleText(record));
  return needle.split(/\s+/).map(t => foldText(t).split(' ')).every(variants => variants.some(v => v && haystack.includes(v)));
}
