export function matchesQuery(record, query) {
  const needle = String(query || '').trim().toLowerCase();
  if (!needle) return true;
  const haystack = foldText(titleText(record));
  // Every typed word must appear, in either spelling: “zürich”, “zuerich” and
  // “zurich” all mean the same place, and the dataset spells it only one way.
  return needle
    .split(/\s+/)
    .every((token) => foldVariants(token).some((variant) => variant && haystack.includes(variant)));
}

/**
 * Case/diacritic folding for the keyword search.
 *
 *   foldText('Zürich')  -> 'zurich zuerich'
 *   foldText('Ecole')   -> 'ecole'
 *
 * Both spellings of a German umlaut are in the haystack (plain “u” and written
 * “ue”), so a visitor with a Swiss or a foreign keyboard finds the same
 * records: “zurich”, “zürich” and “zuerich” all match. The dataset itself is
 * never rewritten — folding only happens while comparing.
 */
export function foldText(value) {
  const plain = String(value ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/ß/g, 'ss');
  const german = String(value ?? '')
    .toLowerCase()
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
  return plain === german ? plain : `${plain} ${german}`;
}

/** The folded spellings of one query word (see `foldText`). */
export function foldVariants(token) {
  return [...new Set(foldText(token).split(' '))];
}

