test('the keyword search folds umlauts in every spelling', () => {
  const zurich = records.filter((record) => matchesQuery(record, 'zürich'));
  assert.ok(zurich.length > 0, 'the seed names Zürich');
  for (const spelling of ['zuerich', 'zurich', 'ZÜRICH', 'Zürich']) {
    assert.equal(
      records.filter((record) => matchesQuery(record, spelling)).length,
      zurich.length,
      `“${spelling}” must find the same records as “zürich”`,
    );
  }
  // Other diacritics are folded too (titles carry French and Italian names).
  assert.equal(
    records.filter((record) => matchesQuery(record, 'geneve')).length,
    records.filter((record) => matchesQuery(record, 'genève')).length,
  );
});

test('folding never invents a match: an unrelated word still finds nothing', () => {
  assert.equal(records.filter((record) => matchesQuery(record, 'xqzwv')).length, 0);
  assert.equal(records.filter((record) => matchesQuery(record, 'siegfriedkarte')).length, records.filter((record) => matchesQuery(record, 'Siegfriedkarte')).length);
});
